import json
with open('/root/autodl-tmp/pacs/profiling_output_bf16_verify/profiling_results.json') as f:
    d = json.load(f)

# Check for NaN in per_problem_ii
nan_count = 0
total_values = 0
for pid, pdata in d['per_problem_ii'].items():
    for phase, phase_data in pdata.items():
        for level, level_data in phase_data.items():
            total_values += 1
            for k, v in level_data.items():
                if v is None or (isinstance(v, float) and v != v):
                    nan_count += 1
                    print(f'NaN found: {pid}/{phase}/{level}/{k}={v}')

print(f'\nTotal entries checked: {total_values}')
print(f'NaN count: {nan_count}')

# PPL summary
print('\n--- PPL by phase ---')
ppl = d.get('perplexity', {})
for phase, phase_data in ppl.items():
    print(f'{phase}:')
    for level, level_data in phase_data.items():
        if isinstance(level_data, dict):
            for cond, val in level_data.items():
                print(f'  {level}/{cond}: {val}')

# n_paired
print('\n--- Per-problem n_paired ---')
for pid, pdata in d['per_problem_ii'].items():
    phases = list(pdata.keys())
    print(f'{pid}: phases={phases}')
